#!/usr/bin/env node
/*
 * Inject the shared conversion layer into every service leaf page.
 *
 * Why: the pricing panel (free photo estimate -> $99 credited assessment ->
 * work from $150) and the trust line were only on the 9 pages generated by
 * generate-appliance-repair-pages.mjs. The pages that actually earn
 * impressions (locks 1.5K, blinds 1.1K, toilets 710, furniture 6.6K) had no
 * price transparency at all, which is the single biggest conversion leak.
 *
 * What it does, idempotently (safe to re-run after any page edit):
 *   1. pricing panel + 4.9-star proof line, inserted before the FAQ section
 *      (or before the related-links section when a page has no FAQ)
 *   2. hero trust chips upgraded to lead with the rating and free estimates
 *
 * Pricing wording is the single source of truth shared with the CRM KB:
 * photo/text estimates free, $99 on-site assessment credited toward the job,
 * work from the $150 minimum, NYC sales tax separate. Never $99 for work.
 *
 * Run: node scripts/inject-conversion-layer.mjs
 */

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname;

const PRICING_PANEL = `        <section class="svc-features" id="pricing" aria-label="Pricing model">
            <div class="container">
                <span class="section-tag">Simple, Honest Pricing</span>
                <h2 class="section-title">Know the Cost <span class="text-accent">Before Anyone Shows Up</span></h2>
                <p class="section-subtitle">4.9&#9733; average across 93 verified reviews on Google, Yelp and Thumbtack. <a href="/reviews/">Read reviews &rarr;</a></p>
                <div class="svc-features__grid">
                    <div class="svc-features__card">
                        <div class="svc-features__icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg></div>
                        <h3>1. Free Photo Estimate</h3>
                        <p>Text photos of the job to <a href="sms:+17753107770">+1 (775) 310-7770</a> or send them through the form &mdash; you get a real answer and a price range for free.</p>
                    </div>
                    <div class="svc-features__card">
                        <div class="svc-features__icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div>
                        <h3>2. $99 On-Site Assessment</h3>
                        <p>Can't tell from photos? We come out and diagnose on site. The $99 is credited toward the job if you hire us &mdash; so the assessment costs $0 when we do the work.</p>
                    </div>
                    <div class="svc-features__card">
                        <div class="svc-features__icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg></div>
                        <h3>3. Work From $150</h3>
                        <p>Every job is quoted and approved before work starts &mdash; no surprises. $150 work minimum; NYC sales tax is added separately where applicable.</p>
                    </div>
                </div>
            </div>
        </section>

`;

/* The DCWP Home Improvement Contractor license (Sept 2026) is the strongest trust
   cue a NYC handyman can show and it was only in the footer. Upgrade whichever
   insured-only chip a page carries; the title attribute holds the license number
   so the chip stays short on mobile. Idempotent. */
const LICENSE_CHIP = `<div class="trust-item" title="NYC DCWP Home Improvement Contractor License No. 2137199-DCWP"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>DCWP-Licensed &amp; Insured</div>`;
const INSURED_ONLY_CHIP_RE = /<div class="trust-item">(\s*<svg[^>]*>(?:(?!<\/svg>)[\s\S])*<\/svg>)\s*(?:Insured Business|Insured &amp; COI-Ready|Insured &amp; COI Ready|Insured &amp; Scope-Checked)\s*<\/div>/g;

// Hero chips: lead with proof instead of generic labels. Only rewritten when
// the page still carries the old generic set.
const OLD_CHIPS_RE = /<div class="svc-hero__trust">[\s\S]*?<\/div>\s*<\/div>/;
const NEW_CHIPS = `<div class="svc-hero__trust">
                    <div class="trust-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>4.9&#9733; &middot; 93 Verified Reviews</div>
                    <div class="trust-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>Free Photo Estimates</div>
                    <div class="trust-item" title="NYC DCWP Home Improvement Contractor License No. 2137199-DCWP"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>DCWP-Licensed &amp; Insured</div>
                    <div class="trust-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Same-Day When Available</div>
                </div>
            </div>`;

const files = execSync('git ls-files "services/*/*/index.html"', { cwd: ROOT, encoding: 'utf8' })
  .split('\n')
  .filter(Boolean);

let panels = 0;
let chips = 0;
const skipped = [];

for (const rel of files) {
  const path = join(ROOT, rel);
  let html = readFileSync(path, 'utf8');
  let touched = false;

  if (!html.includes('id="pricing"')) {
    // Prefer inserting before the FAQ; fall back to the related-links block.
    const anchors = [
      /[ \t]*<section class="svc-faq"/,
      /[ \t]*<section class="svc-related"/,
      /[ \t]*<section class="svc-testimonials"/,
      // Premium/custom pages (tadelakt, decorative plaster, gazebo) use their
      // own section classes; fall back to the FAQ or closing CTA.
      /[ \t]*<section class="faq"/,
      /[ \t]*<section class="svc-cta"/,
    ];
    const hit = anchors.map((re) => html.search(re)).find((i) => i > -1);
    if (hit === undefined) {
      skipped.push(rel);
    } else {
      html = html.slice(0, hit) + PRICING_PANEL + html.slice(hit);
      panels++;
      touched = true;
    }
  }

  if (INSURED_ONLY_CHIP_RE.test(html)) {
    html = html.replace(INSURED_ONLY_CHIP_RE, () => LICENSE_CHIP);
    chips++;
    touched = true;
  }

  if (html.includes('svc-hero__trust') && !html.includes('93 Verified Reviews')) {
    const next = html.replace(OLD_CHIPS_RE, NEW_CHIPS);
    if (next !== html) {
      html = next;
      chips++;
      touched = true;
    }
  }

  if (touched) writeFileSync(path, html);
}

console.log(`Pricing panel added to ${panels} pages; hero chips upgraded on ${chips} pages.`);
if (skipped.length) console.log(`No anchor found (left untouched): ${skipped.join(', ')}`);

/* Audience landers priced nothing on-page. Each gets the calculator whose tiers match
   the visitor: property managers see apartment-turnover by unit size, restaurants see
   commercial refrigeration triage, the rest the general-repairs hub picker. Inserted
   once, before the page's FAQ section. */
const LANDER_CALCULATORS = {
  'same-day-handyman-nyc/index.html': 'hub-general-repairs',
  'for-restaurants/index.html': 'commercial-refrigeration',
  'for-property-managers/index.html': 'apartment-turnover',
  'new-apartment-setup/index.html': 'hub-furniture-assembly',
  'preventive-maintenance/index.html': 'hub-general-repairs',
};
for (const [rel, config] of Object.entries(LANDER_CALCULATORS)) {
  const path = join(ROOT, rel);
  if (!existsSync(path)) continue;
  const html = readFileSync(path, 'utf8');
  if (html.includes('data-module="calculator"')) continue;
  const faq = html.match(/([ \t]*)<section[^>]*\sid="faq"[^>]*>/);
  if (!faq) { console.log(`  lander ${rel}: no #faq anchor, calculator not added`); continue; }
  const indent = faq[1];
  const section = `${indent}<section class="spoke-module" id="calculator">\n${indent}    <div class="container">\n${indent}        <div data-module="calculator" data-config="${config}"></div>\n${indent}    </div>\n${indent}</section>\n\n`;
  writeFileSync(path, html.replace(faq[0], () => section + faq[0]));
  console.log(`  lander ${rel}: calculator ${config} added`);
}
